    :root {
      color-scheme: light;
      --ink: #172a46;
      --muted: #64748b;
      --line: #cbd5e1;
      --blue: #2563eb;
      --green: #16a34a;
      --bg: #f8fafc;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Arial, "Noto Sans KR", sans-serif;
      color: var(--ink);
      background: var(--bg);
    }
    .ahn-shell { min-height: 100vh; display: flex; flex-direction: column; }
    .ahn-topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 24px 28px;
      border-bottom: 1px solid var(--line);
      background: #fff;
    }
    .ahn-topbar > * {
      margin-bottom: 16px;
      margin-right: 16px;
}
    .ahn-brand { display: flex; align-items: baseline; min-width: 0; }
    .ahn-brand > * {
      margin-bottom: 14px;
      margin-right: 14px;
}
    .ahn-brand h1 { margin: 0; font-size: 30px; letter-spacing: 0; }
    .ahn-brand span { color: var(--muted); font-size: 17px; white-space: nowrap; }
    .ahn-actions { display: flex; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
    .ahn-actions > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    button, .ahn-download {
      border: 1px solid #9fb6d6;
      background: #fff;
      color: var(--ink);
      border-radius: 7px;
      min-height: 42px;
      padding: 9px 14px;
      font-size: 15px;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
    }
    button.primary { border-color: var(--blue); background: var(--blue); color: #fff; }
    button:disabled, .ahn-download[aria-disabled="true"] {
      opacity: .48;
      cursor: not-allowed;
      pointer-events: none;
    }
    .ahn-main { padding: 18px 28px 28px; display: block; }
    .ahn-main > * {
      margin-bottom: 16px;
}
    .ahn-panel {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 16px;
    }
    .ahn-hidden-input { display: none; }
    .ahn-drop {
      border: 1px dashed #9fb6d6;
      border-radius: 8px;
      min-height: 150px;
      color: #476483;
      background: #f8fbff;
      text-align: center;
      padding: 18px;
      display: block;
      place-items: center;
    }
    .ahn-drop.dragover { border-color: var(--blue); background: #eef6ff; }
    .ahn-drop-title {
      margin: 0 0 5px;
      color: var(--ink);
      font-size: 18px;
      font-weight: 800;
    }
    .ahn-drop-text { margin: 0; color: #476483; line-height: 1.45; }
    .ahn-bundle-actions {
      margin-top: 13px;
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      align-items: center;
    }
    .ahn-bundle-actions > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .ahn-bundle-actions button { min-height: 38px; padding: 7px 12px; font-size: 14px; }
    .ahn-bundle-meta {
      margin-top: 10px;
      color: var(--muted);
      font-size: 13px;
      text-align: center;
    }
    .ahn-files {
      margin-top: 12px;
      display: flex;
      flex-wrap: wrap;
    }
    .ahn-files > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .ahn-chip {
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: 6px 10px;
      background: #fff;
      color: #334155;
      font-size: 13px;
      max-width: 300px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .ahn-status-stack { display: block; }
    .ahn-status-stack > * {
      margin-bottom: 8px;
}
    .ahn-status {
      min-height: 38px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 10px 8px 12px;
      border-radius: 7px;
      background: #ecfdf5;
      border: 1px solid #bbf7d0;
      color: #166534;
      font-size: 14px;
      transition: opacity 180ms ease, transform 180ms ease;
    }
    .ahn-status > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .ahn-status.error { background: #fef2f2; border-color: #fecaca; color: #991b1b; }
    .ahn-status.is-hiding { opacity: 0; transform: translateY(-4px); }
    .ahn-status-text { min-width: 0; overflow-wrap: anywhere; }
    .ahn-status-close {
      min-height: 0;
      border: 0;
      background: transparent;
      color: currentColor;
      cursor: pointer;
      font-size: 17px;
      font-weight: 800;
      line-height: 1;
      padding: 2px 4px;
      opacity: .72;
    }
    .ahn-status-close:hover { opacity: 1; background: rgba(15, 23, 42, .06); }
    .ahn-progress {
      display: none;
      padding: 11px 14px 12px;
      border: 1px solid #bfdbfe;
      border-radius: 8px;
      background: #eff6ff;
      color: #1e3a8a;
      font-size: 13px;
    }
    .ahn-progress.is-visible {
      position: fixed;
      left: 50%;
      top: 50%;
      z-index: 70;
      display: block;
      max-width: 560px;
      width: calc(100vw - 32px);
      transform: translate(-50%, -50%);
      box-shadow: 0 18px 48px rgba(15, 23, 42, 0.18);
    }
    .ahn-progress.is-error {
      border-color: #fecaca;
      background: #fef2f2;
      color: #991b1b;
    }
    .ahn-progress-stage { display: none; }
    .ahn-progress-stage.is-visible { display: block; }
    .ahn-progress-stage + .ahn-progress-stage {
      margin-top: 11px;
      padding-top: 10px;
      border-top: 1px solid rgba(30, 64, 175, .16);
    }
    .ahn-progress-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 7px;
      font-weight: 700;
    }
    .ahn-progress-row > * {
      margin-bottom: 12px;
      margin-right: 12px;
}
    .ahn-progress-track {
      overflow: hidden;
      height: 7px;
      border-radius: 999px;
      background: #dbeafe;
    }
    .ahn-progress-bar {
      width: 0%;
      height: 100%;
      border-radius: inherit;
      background: var(--blue);
      transition: width 240ms ease;
    }
    .ahn-collect-progress .ahn-progress-track { position: relative; }
    .ahn-collect-progress .ahn-progress-bar {
      position: absolute;
      left: 0;
      width: 38%;
      animation: ahn-collect-progress 1.05s ease-in-out infinite;
      transition: none;
    }
    .ahn-upload-progress .ahn-progress-bar { background: #16a34a; }
    .ahn-progress.is-error .ahn-progress-bar { background: #dc2626; }
    @keyframes ahn-collect-progress {
      0% { transform: translateX(-110%); }
      100% { transform: translateX(280%); }
    }
    @media (prefers-reduced-motion: reduce) {
      .ahn-collect-progress .ahn-progress-bar { animation-duration: 2.4s; }
    }
    .ahn-result {
      display: block;
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 16px;
    }
    .ahn-result > * {
      margin-bottom: 14px;
}
    .ahn-result[hidden] { display: none; }
    .ahn-summary {
      display: flex;
      grid-template-columns: repeat(4, minmax(120px, 1fr));
      flex-wrap: wrap;
    }
    .ahn-summary > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .ahn-summary > * {
      flex: 0 1 calc(25% - 10px);
      min-width: 0;
      max-width: calc(25% - 10px);
}
    .ahn-summary-item {
      border: 1px solid #d8e2ef;
      border-radius: 8px;
      padding: 12px;
      background: #fbfdff;
    }
    .ahn-summary-item span { display: block; color: var(--muted); font-size: 13px; }
    .ahn-summary-item strong { display: block; margin-top: 5px; font-size: 22px; color: var(--ink); }
    .ahn-downloads { display: flex; flex-wrap: wrap; }
    .ahn-downloads > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .ahn-transfer {
      display: block;
      padding: 16px;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: #fff;
    }
    .ahn-transfer > * {
      margin-bottom: 12px;
}
    .ahn-transfer-head,
    .ahn-transfer-actions {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
    }
    .ahn-transfer-head > *,.ahn-transfer-actions > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .ahn-transfer-head strong { color: var(--ink); }
    .ahn-request-picker {
      display: flex;
      grid-template-columns: auto minmax(240px, 1fr);
      flex-wrap: wrap;
    }
    .ahn-request-picker > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .ahn-request-picker > * {
      flex: 0 1 calc(50% - 10px);
      min-width: 0;
      max-width: calc(50% - 10px);
}
    .ahn-request-picker select,
    .ahn-transfer-grid input {
      width: 100%;
      min-width: 0;
      min-height: 40px;
      border: 1px solid #bfd0e4;
      border-radius: 6px;
      background: #fff;
      color: var(--ink);
      padding: 8px 10px;
      font: inherit;
    }
    .ahn-request-detail {
      display: flex;
      flex-wrap: wrap;
      min-height: 22px;
      color: #475569;
      font-size: 13px;
    }
    .ahn-request-detail > * {
      margin-bottom: 7px;
      margin-right: 14px;
}
    .ahn-request-detail.is-empty { color: var(--muted); }
    .ahn-request-detail b { margin-right: 4px; color: #1e3a5f; }
    .ahn-transfer-grid {
      display: flex;
      grid-template-columns: repeat(4, minmax(150px, 1fr));
      flex-wrap: wrap;
    }
    .ahn-transfer-grid > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .ahn-transfer-grid > * {
      flex: 0 1 calc(25% - 10px);
      min-width: 0;
      max-width: calc(25% - 10px);
}
    .ahn-transfer-grid label { min-width: 0; color: #475569; font-size: 13px; }
    .ahn-transfer-grid span { display: block; margin-bottom: 5px; font-weight: 700; }
    .ahn-empty {
      min-height: 220px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--muted);
      font-weight: 700;
      text-align: center;
      border: 1px dashed var(--line);
      border-radius: 8px;
      background: #fff;
    }
    .ahn-busy {
      position: fixed;
      top: 0;
      right: 0;
      bottom: 0;
      left: 0;
      display: none;
      align-items: center;
      justify-content: center;
      background: rgba(255,255,255,.74);
      z-index: 50;
      color: var(--ink);
      font-weight: 700;
    }
    .ahn-busy.show { display: none; }
    .ahn-recovery { border: 1px solid #bfcee0; border-radius: 8px; padding: 12px 14px; margin: 12px 0; background: #eff6ff; color: #244565; display: flex; align-items: center; flex-wrap: wrap; }
    .ahn-recovery > * {
      margin-bottom: 12px;
      margin-right: 12px;
}
    .ahn-recovery span { flex: 1 1 260px; min-width: 0; overflow-wrap: anywhere; }
    .ahn-recovery button { white-space: nowrap; flex-shrink: 0; }
    .ahn-transfer-stats { margin: 12px 0; padding: 12px 14px; border: 1px solid #bfcee0; border-radius: 8px; background: #f8fbff; color: #244565; font-size: 13px; overflow-wrap: anywhere; }
    .ahn-transfer-stats summary { cursor: pointer; margin-top: 6px; }
    #ahn-transfer-detail { white-space: pre-line; line-height: 1.6; }
    @media (max-width: 900px) {
      .ahn-topbar { align-items: flex-start; padding: 18px 16px; }
      .ahn-brand { display: block; }
      .ahn-brand h1 { font-size: 25px; }
      .ahn-brand span { display: block; margin-top: 4px; white-space: normal; }
      .ahn-main { padding: 14px 12px 24px; }
      .ahn-topbar { flex-wrap: wrap; }
      .ahn-brand { flex: 1 1 100%; }
      .ahn-actions { width: 100%; justify-content: flex-end; }
      button, .ahn-download { min-height: 40px; padding: 8px 11px; font-size: 14px; }
      .ahn-summary { grid-template-columns: repeat(2, minmax(120px, 1fr)); }
      .ahn-summary > * {
            flex: 0 1 calc(50% - 12px);
            min-width: 0;
            max-width: calc(50% - 12px);
      }
      .ahn-request-picker { grid-template-columns: 1fr; }
      .ahn-request-picker > * {
            flex: 0 1 100%;
            min-width: 0;
            max-width: 100%;
      }
      .ahn-transfer-grid { grid-template-columns: repeat(2, minmax(120px, 1fr)); }
      .ahn-transfer-grid > * {
            flex: 0 1 calc(50% - 12px);
            min-width: 0;
            max-width: calc(50% - 12px);
      }
    }

styles.5a6fb8e053972fa9e6a44cb46ff7c74c2e27b9ad:
/* Shared TEM work history / XRD project manager. Keep controls self-contained. */
.ristWorkManager[hidden], .ristWorkManager [hidden] { display: none !important; }
.ristWorkManager { position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 10000; background: rgba(14,31,48,.48); display: flex; align-items: center; justify-content: center; padding: 16px; box-sizing: border-box; font: 14px/1.5 Arial, 'Malgun Gothic', sans-serif; color: #293e52; }
.ristWorkManager .projectPanel { display: flex; flex-direction: column; width: 960px; max-width: 100%; height: 820px; max-height: 100%; overflow: hidden; box-sizing: border-box; padding: 20px; background: #fff; border-radius: 10px; box-shadow: 0 12px 40px rgba(0,0,0,.24); }
.ristWorkManager .projectPanel > * { flex-shrink: 0; }
.ristWorkManager .projectPanel .projectRows { flex: 1 1 180px; min-height: 60px; overflow-y: auto; overscroll-behavior: contain; }
.ristWorkManager .projectHeading { display: flex; align-items: center; justify-content: space-between; }
.ristWorkManager .projectHeading > * { margin-bottom: 12px; margin-right: 12px; }
.ristWorkManager .projectHeading h2 { font-size: 20px; font-weight: 700; line-height: 1.5; margin: 0; color: #163e62; }
.ristWorkManager .projectHelp { color: #52677c; font-size: 13px; line-height: 1.6; margin: 12px 0; overflow-wrap: break-word; }
.ristWorkManager .projectPolicy { padding: 10px 12px; background: #f3f6fa; border: 1px solid #d6e0ea; border-radius: 5px; }
.ristWorkManager .projectFilters { display: flex; flex-wrap: wrap; align-items: center; padding: 12px 0; border-bottom: 1px solid #d6e0ea; }
.ristWorkManager .projectFilters > * { margin-bottom: 10px; margin-right: 10px; }
.ristWorkManager .projectFilters > div { display: flex; }
.ristWorkManager .projectFilters > div > * { margin-bottom: 6px; margin-right: 6px; }
.ristWorkManager label { font: 13px/1.6 Arial, 'Malgun Gothic', sans-serif; color: #52677c; }
.ristWorkManager .projectFilters label { flex: 1 1 200px; min-width: 0; display: flex; align-items: center; margin: 0; white-space: nowrap; }
.ristWorkManager .projectFilters label > * { margin-bottom: 8px; margin-right: 8px; }
.ristWorkManager .projectFilters input { flex: 1; width: 0; min-width: 0; }
.ristWorkManager input, .ristWorkManager select { font: 13px/1.5 Arial, 'Malgun Gothic', sans-serif; box-sizing: border-box; min-height: 36px; max-width: 100%; width: 100%; padding: 8px 10px; border: 1px solid #d6e0ea; border-radius: 5px; color: #293e52; background: #fff; }
.ristWorkManager input[readonly] { background: #f3f6fa; }
.ristWorkManager .projectRow { display: flex; flex-wrap: wrap; align-items: center; padding: 10px 0; border-bottom: 1px solid #d6e0ea; }
.ristWorkManager .projectRow > * { margin-bottom: 8px; margin-right: 8px; }
.ristWorkManager .projectRowInfo { flex: 1 1 200px; min-width: 0; }
.ristWorkManager .projectNameLabel { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.ristWorkManager input[type=checkbox] { width: 16px; height: 16px; min-height: 0; flex: 0 0 16px; margin: 0 4px 0 0; }
.ristWorkManager .projectSort, .ristWorkManager .projectBulk, .ristWorkManager .projectPager { display: flex; align-items: center; flex-wrap: wrap; padding-top: 10px; font-size: 13px; }
.ristWorkManager .projectSort > *,.ristWorkManager .projectBulk > *,.ristWorkManager .projectPager > * { margin-bottom: 8px; margin-right: 8px; }
.ristWorkManager .projectBulk label, .ristWorkManager .projectSort label { display: flex; align-items: center; margin: 0; white-space: nowrap; }
.ristWorkManager .projectBulk label > *,.ristWorkManager .projectSort label > * { margin-bottom: 4px; margin-right: 4px; }
.ristWorkManager .projectSort select { width: auto; min-width: 60px; padding: 6px; }
.ristWorkManager .projectPager { justify-content: center; border-top: 1px solid #d6e0ea; }
.ristWorkManager .projectPager span { flex-shrink: 0; white-space: nowrap; }
.ristWorkManager .projectPanel button, .ristWorkManager .projectRowActions a { display: inline-flex; align-items: center; justify-content: center; min-height: 34px; padding: 6px 10px; border: 1px solid #d6e0ea; border-radius: 5px; color: #163e62; background: #fff; font: 13px/1.5 Arial, 'Malgun Gothic', sans-serif; box-sizing: border-box; white-space: nowrap; flex-shrink: 0; cursor: pointer; text-decoration: none; box-shadow: none; }
.ristWorkManager button:hover:not(:disabled), .ristWorkManager .projectRowActions a:hover { background: #e9f2fa; color: #163e62; }
.ristWorkManager button:disabled { cursor: default; opacity: .5; }
.ristWorkManager button[aria-pressed=true] { background: #e9f2fa; border-color: #8cb4d3; color: #163e62; font-weight: 700; }
.ristWorkManager :focus { outline: 2px solid #1768a0; outline-offset: 2px; }
.ristWorkManager .projectRowInfo p { color: #52677c; font-size: 12px; margin: 6px 0 0; overflow-wrap: break-word; }
.ristWorkManager .projectRowActions { display: flex; flex-wrap: wrap; }
.ristWorkManager .projectRowActions > * { margin-bottom: 6px; margin-right: 6px; }
.ristWorkManager button.projectDanger { color: #9d2929; border-color: #e5bcbc; }
.ristWorkManager .projectNotice { min-height: 20px; margin: 12px 0; color: #52677c; font-size: 13px; overflow-wrap: break-word; }
.ristWorkManager .projectNotice.error { color: #9d2929; }
.ristWorkManager .projectEmpty { padding: 28px 0; text-align: center; color: #52677c; }
@media (max-width: 520px) {
  .ristWorkManager { padding: 8px; }
  .ristWorkManager .projectPanel { padding: 14px; }
  .ristWorkManager .projectRowActions { width: 100%; justify-content: flex-end; }
  .ristWorkManager .projectHelp { font-size: 12px; margin: 8px 0; }
  .ristWorkManager .projectNotice { margin: 8px 0; }
}
@media (max-height: 540px) {
  .ristWorkManager .projectPanel { overflow-y: auto; }
  .ristWorkManager .projectPanel .projectRows { flex: none; max-height: 240px; }
}

styles.5ab81c3581fee9f174c74b1e0b72b4b6b04343df:
html, body {
  margin: 0;
  min-height: 100%;
  background: #f8fafc;
  color: #1f2933;
  font-family: Arial, "Noto Sans KR", sans-serif;
}
body { overflow-x: hidden; }
.raman-app-bar {
  display: flex;
  align-items: center;
  min-height: 54px;
  padding: 8px 22px;
  border-bottom: 1px solid #d9e2ec;
  background: #fff;
  box-sizing: border-box;
}
.raman-app-bar > * {
  margin-bottom: 12px;
  margin-right: 12px;
}
.raman-brand {
  display: flex;
  flex-shrink: 0;
  max-width: 100%;
  align-items: baseline;
  min-width: 0;
}
.raman-brand > * {
  margin-bottom: 9px;
  margin-right: 9px;
}
.raman-brand strong {
  color: #102a43;
  font-size: 18px;
}
.raman-brand span {
  color: #52606d;
  font-size: 12px;
}
/* Keep action captions intact; their containers wrap whole controls instead. */
button,
.raman-report-option-button {
  white-space: nowrap;
  word-break: normal;
  overflow-wrap: normal;
}
.raman-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
  margin-left: auto;
}
.raman-actions > * {
  margin-bottom: 8px;
  margin-right: 8px;
}
.raman-origin-toggle {
  display: inline-flex;
  align-items: center;
  height: 30px;
  padding: 0 8px;
  border: 1px solid #9fb3c8;
  border-radius: 4px;
  background: #fff;
  color: #243b53;
  cursor: pointer;
  font-size: 11px;
  white-space: nowrap;
  box-sizing: border-box;
}
.raman-origin-toggle > * {
  margin-bottom: 5px;
  margin-right: 5px;
}
.raman-origin-toggle input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: #2563eb;
}
.raman-status {
  max-width: 360px;
  overflow: hidden;
  color: #52606d;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.raman-file-button,
.raman-clear-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 30px;
  border: 1px solid #9fb3c8;
  border-radius: 4px;
  background: #f5f7fa;
  color: #243b53;
  cursor: pointer;
  font-size: 11px;
  padding: 0 10px;
  box-sizing: border-box;
  text-decoration: none;
  white-space: nowrap;
}
.raman-file-button:hover,
.raman-clear-button:hover {
  border-color: #486581;
  background: #e8eef5;
}
.raman-clear-button[hidden],
.raman-file-input { display: none; }
.raman-library-band {
  display: flex;
  align-items: flex-start;
  min-height: 68px;
  padding: 7px 22px;
  border-bottom: 1px solid #d9e2ec;
  background: #f8fafc;
  box-sizing: border-box;
}
.raman-library-band > * {
  margin-bottom: 10px;
  margin-right: 10px;
}
.raman-library-title {
  flex: 0 0 auto;
  margin-top: 9px;
  color: #334e68;
  font-size: 11px;
  font-weight: 700;
}
.raman-library-filter {
  flex: 0 0 150px;
  width: 150px;
  height: 30px;
  border: 1px solid #bcccdc;
  border-radius: 4px;
  background: #fff;
  color: #243b53;
  font: 11px Arial, "Noto Sans KR", sans-serif;
  padding: 0 9px;
  box-sizing: border-box;
}
.raman-library-list {
  display: flex;
  align-content: flex-start;
  align-items: flex-start;
  flex-wrap: wrap;
  min-width: 0;
  flex: 1 1 auto;
  max-height: 62px;
  overflow-x: hidden;
  overflow-y: auto;
}
.raman-library-list > * {
  margin-bottom: 6px;
  margin-right: 6px;
}
.raman-library-item {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  max-width: 300px;
  height: 28px;
  border: 1px solid #bcccdc;
  border-radius: 4px;
  background: #fff;
  color: #334e68;
  font-size: 11px;
  box-sizing: border-box;
}
.raman-library-item.is-selected {
  border-color: #3e7ca6;
  background: #edf6fb;
  color: #174b6d;
}
.raman-library-item.is-invalid {
  border-color: #f5b7b1;
  color: #9b2c2c;
}
.raman-library-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
}
.raman-library-name {
  min-width: 0;
  max-width: 190px;
  height: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  overflow: hidden;
  padding: 0 6px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.raman-library-count,
.raman-library-state,
.raman-library-empty {
  color: #7b8794;
  font-size: 10px;
  padding: 0 6px;
  white-space: nowrap;
}
.raman-library-new,
.raman-library-upload {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  height: 30px;
  border: 1px solid #9fb3c8;
  border-radius: 4px;
  background: #fff;
  color: #243b53;
  cursor: pointer;
  font-size: 11px;
  padding: 0 10px;
  box-sizing: border-box;
}
.raman-library-modal {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 60;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(15,23,42,0.24);
}
.raman-library-modal.is-visible { display: flex; }
.raman-library-dialog {
  display: flex;
  flex-direction: column;
  max-width: 920px;
  width: calc(100vw - 28px);
  max-height: calc(100vh - 28px);
  border: 1px solid #bcccdc;
  border-radius: 6px;
  background: #fff;
  box-shadow: 0 16px 42px rgba(15,23,42,0.2);
}
.raman-library-dialog-header,
.raman-library-dialog-actions {
  display: flex;
  align-items: center;
  padding: 11px 14px;
  border-bottom: 1px solid #d9e2ec;
}
.raman-library-dialog-header > *,.raman-library-dialog-actions > * {
  margin-bottom: 8px;
  margin-right: 8px;
}
.raman-library-dialog-actions {
  justify-content: flex-end;
  flex-wrap: wrap;
  border-top: 1px solid #d9e2ec;
  border-bottom: 0;
}
.raman-library-dialog-heading {
