#raman-plot .rist-ratio-candidates { z-index:60; width:290px; max-width:calc(100% - 16px); max-height:65%; overflow:auto; }
#raman-plot .rist-ratio-candidates [data-candidates-list] button {
  display:block; width:100%; text-align:left; white-space:pre-line; word-wrap:break-word; overflow-wrap:anywhere;
  margin:5px 0; padding:8px;
}
#raman-plot .rist-ratio-overlay { position:absolute; top:0; left:0; width:100%; height:100%; pointer-events:none; z-index:48; }
#raman-plot .rist-ratio-marker {
  position:absolute; width:22px; height:22px; box-sizing:border-box; transform:translate(-50%,-50%);
  border:3px solid #2563eb; border-radius:50%; box-shadow:0 0 0 2px #fff; background:transparent;
}
#raman-plot .rist-ratio-marker.denominator { width:28px; height:28px; border-color:#e87500; border-radius:3px; }
#raman-plot .rist-ratio-marker.hover { width:34px; height:34px; border:2px dashed #334e68; }
#raman-plot .rist-ratio-marker > span {
  position:absolute; left:19px; bottom:20px; white-space:nowrap; border:1px solid #2563eb;
  background:#fff; color:#1d4ed8; border-radius:4px; padding:2px 5px; font:bold 12px/1.5 Arial,sans-serif;
}
#raman-plot .rist-ratio-marker.denominator > span { top:26px; bottom:auto; border-color:#c65d00; color:#a84e00; }
#raman-plot .rist-ratio-marker.edge-right > span { left:auto; right:20px; }
#raman-plot .rist-ratio-marker.numerator.edge-top > span { bottom:auto; top:22px; }
#raman-plot .rist-ratio-marker.hover > span { display:none; }
#raman-plot .rist-ratio-hover-tip { position:absolute; width:250px; max-width:calc(100% - 12px); box-sizing:border-box; padding:8px 10px; white-space:pre-line; word-wrap:break-word; background:#fff; border:1px solid #627d98; border-radius:5px; box-shadow:0 2px 8px #0002; font:12px/1.5 Arial,sans-serif; color:#102a43; }
#raman-plot.rist-ratio-focus .rist-ratio-muted { opacity:.18 !important; }
#raman-plot.rist-ratio-picking .hoverlayer { visibility:hidden; }
#raman-plot .rist-ratio-selection[hidden],
#raman-plot .rist-ratio-selection [hidden],
#raman-plot .rist-ratio-candidates[hidden],
#raman-plot .rist-ratio-overlay [hidden] { display:none !important; }
@media (max-width:600px) {
  #raman-plot .rist-ratio-selection { top:80px; right:8px; width:250px; max-height:55%; padding:8px; }
}
@media print {
  #raman-plot .rist-ratio-selection, #raman-plot .rist-ratio-candidates, #raman-plot .rist-ratio-overlay { display:none !important; }
  #raman-plot.rist-ratio-focus .rist-ratio-muted { opacity:1 !important; }
}
#raman-plot .rist-ratio-batch {
  position:absolute; z-index:54; top:90px; right:12px; width:355px; max-width:calc(100% - 24px);
  max-height:calc(100% - 105px); overflow:auto; box-sizing:border-box; padding:12px;
  background:#fff; color:#102a43; border:1px solid #9fb3c8; border-radius:8px;
  box-shadow:0 4px 18px rgba(15,23,42,.18); font:12px/1.5 Arial,sans-serif; text-align:left;
}
#raman-plot .rist-ratio-batch.reviewing { width:760px; }
#raman-plot .rist-ratio-batch.collapsed { width:280px; }
#raman-plot .rist-ratio-batch.collapsed > :not(header) { display:none !important; }
#raman-plot .rist-ratio-batch header { display:flex; align-items:center; justify-content:space-between; }
#raman-plot .rist-ratio-batch p { margin:8px 0; }
#raman-plot .rist-ratio-batch button {
  white-space:nowrap; padding:5px 8px; border:1px solid #b8c5d1; border-radius:4px;
  background:#f8fafc; color:#102a43; font:inherit; cursor:pointer;
}
#raman-plot .rist-ratio-batch button[aria-pressed='true'] { background:#e0f2fe; border-color:#2563eb; }
#raman-plot .rist-ratio-batch button:disabled { opacity:.5; cursor:default; }
#raman-plot .rist-ratio-range-input { display:flex; align-items:center; margin:6px 0; flex-wrap:wrap; }
#raman-plot .rist-ratio-range-input > * { margin-bottom:4px; margin-right:4px; }
#raman-plot .rist-ratio-range-input input { width:70px; min-width:0; padding:4px; box-sizing:border-box; font:inherit; }
#raman-plot .rist-ratio-batch-table { overflow:auto; max-height:240px; margin-bottom:10px; }
#raman-plot .rist-ratio-batch table { width:100%; border-collapse:collapse; font:inherit; }
#raman-plot .rist-ratio-batch td, #raman-plot .rist-ratio-batch th { padding:6px; border-bottom:1px solid #d8e2eb; text-align:left; min-width:65px; }
#raman-plot .rist-ratio-batch td:first-child, #raman-plot .rist-ratio-batch th:first-child { min-width:25px; }
#raman-plot .rist-ratio-batch tr:hover, #raman-plot .rist-ratio-batch tr:focus { background:#eff6ff; }
#raman-plot .rist-ratio-range-surface { position:absolute; z-index:46; pointer-events:none; overflow:hidden; }
#raman-plot .rist-ratio-range-surface.picking { pointer-events:auto; cursor:crosshair; touch-action:none; }
#raman-plot .rist-ratio-range-band { position:absolute; top:0; height:100%; box-sizing:border-box; background:rgba(37,99,235,.1); border:1px solid #2563eb; color:#1d4ed8; font:bold 12px Arial,sans-serif; white-space:nowrap; pointer-events:none; }
#raman-plot .rist-ratio-range-band.denominator { border-color:#c65d00; background:rgba(232,117,0,.1); color:#a84e00; }
#raman-plot .rist-ratio-batch [hidden], #raman-plot .rist-ratio-batch[hidden],
#raman-plot .rist-ratio-range-surface[hidden], #raman-plot .rist-ratio-range-band[hidden] { display:none !important; }
@media (max-width:600px) {
  #raman-plot .rist-ratio-batch { top:80px; right:8px; max-height:55%; padding:8px; }
  #raman-plot .rist-ratio-batch table, #raman-plot .rist-ratio-batch tbody,
  #raman-plot .rist-ratio-batch tr, #raman-plot .rist-ratio-batch td { display:block; width:auto; }
  #raman-plot .rist-ratio-batch thead { display:none; }
  #raman-plot .rist-ratio-batch tr { border:1px solid #d8e2eb; border-radius:4px; margin-bottom:6px; padding:4px 0; }
  #raman-plot .rist-ratio-batch td { border:0; min-width:0; padding:3px 6px; overflow-wrap:break-word; }
  #raman-plot .rist-ratio-batch td:before { content:attr(data-label) " · "; font-weight:bold; }
}
@media print {
  #raman-plot .rist-ratio-batch, #raman-plot .rist-ratio-range-surface { display:none !important; }
}

styles.69e5aa7ccf7e9b46e285b421925ca0c05ff987ef:
    :root {
      color-scheme: light;
      --ink: #172a46;
      --muted: #64748b;
      --line: #cbd5e1;
      --blue: #2563eb;
      --green: #16a34a;
      --bg: #f8fafc;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Arial, "Noto Sans KR", sans-serif;
      color: var(--ink);
      background: var(--bg);
    }
    .xrd-shell { min-height: 100vh; display: flex; flex-direction: column; }
    .xrd-topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 24px 28px;
      border-bottom: 1px solid var(--line);
      background: #fff;
    }
    .xrd-topbar > * {
      margin-bottom: 16px;
      margin-right: 16px;
}
    .xrd-brand { display: flex; align-items: baseline; min-width: 0; }
    .xrd-brand > * {
      margin-bottom: 14px;
      margin-right: 14px;
}
    .xrd-brand h1 { margin: 0; font-size: 30px; letter-spacing: 0; }
    .xrd-brand span { color: var(--muted); font-size: 17px; white-space: nowrap; }
    .xrd-actions { display: flex; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
    .xrd-actions > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    button, .xrd-download {
      border: 1px solid #9fb6d6;
      background: #fff;
      color: var(--ink);
      border-radius: 7px;
      min-height: 42px;
      padding: 9px 14px;
      font-size: 15px;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
    }
    button.primary { border-color: var(--blue); background: var(--blue); color: #fff; }
    button:disabled, .xrd-download[aria-disabled="true"] {
      opacity: .48;
      cursor: not-allowed;
      pointer-events: none;
    }
    .xrd-main { padding: 18px 28px 28px; display: block; }
    .xrd-main > * {
      margin-bottom: 16px;
}
    .xrd-panel {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 16px;
    }
    .xrd-hidden-input { display: none; }
    .xrd-check {
      display: flex;
      align-items: center;
      min-height: 42px;
      font-weight: 700;
    }
    .xrd-check > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .xrd-drop {
      border: 1px dashed #9fb6d6;
      border-radius: 8px;
      min-height: 122px;
      color: #476483;
      background: #f8fbff;
      text-align: center;
      padding: 18px;
      display: block;
      place-items: center;
    }
    .xrd-drop.dragover { border-color: var(--blue); background: #eef6ff; }
    .xrd-drop-title {
      margin: 0 0 5px;
      color: var(--ink);
      font-size: 18px;
      font-weight: 800;
    }
    .xrd-drop-text { margin: 0; color: #476483; line-height: 1.45; }
    .xrd-bundle-actions {
      margin-top: 13px;
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      align-items: center;
    }
    .xrd-bundle-actions > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .xrd-bundle-actions button { min-height: 38px; padding: 7px 12px; font-size: 14px; }
    .xrd-bundle-meta {
      margin-top: 10px;
      color: var(--muted);
      font-size: 13px;
      text-align: center;
    }
    .xrd-files {
      margin-top: 12px;
      display: flex;
      flex-wrap: wrap;
    }
    .xrd-files > * {
      margin-bottom: 8px;
      margin-right: 8px;
}
    .xrd-chip {
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: 6px 10px;
      background: #fff;
      color: #334155;
      font-size: 13px;
      max-width: 280px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .xrd-status-stack {
      display: block;
    }
    .xrd-status-stack > * {
      margin-bottom: 8px;
}
    .xrd-status {
      min-height: 38px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 10px 8px 12px;
      border-radius: 7px;
      background: #ecfdf5;
      border: 1px solid #bbf7d0;
      color: #166534;
      font-size: 14px;
      transition: opacity 180ms ease, transform 180ms ease;
    }
    .xrd-status > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-status.error { background: #fef2f2; border-color: #fecaca; color: #991b1b; }
    .xrd-status.is-hiding { opacity: 0; transform: translateY(-4px); }
    .xrd-status-text { min-width: 0; overflow-wrap: anywhere; }
    .xrd-status-close {
      min-height: 0;
      border: 0;
      background: transparent;
      color: currentColor;
      cursor: pointer;
      font-size: 17px;
      font-weight: 800;
      line-height: 1;
      padding: 2px 4px;
      opacity: .72;
    }
    .xrd-status-close:hover { opacity: 1; background: rgba(15, 23, 42, .06); }
    .xrd-progress {
      display: none;
      padding: 11px 14px 12px;
      border: 1px solid #bfdbfe;
      border-radius: 8px;
      background: #eff6ff;
      color: #1e3a8a;
      font-size: 13px;
    }
    .xrd-progress.is-visible {
      position: fixed;
      left: 50%;
      top: 50%;
      z-index: 70;
      display: block;
      max-width: 560px;
      width: calc(100vw - 32px);
      transform: translate(-50%, -50%);
      box-shadow: 0 18px 48px rgba(15, 23, 42, 0.18);
    }
    .xrd-progress.is-visible > * {
      margin-bottom: 11px;
}
    .xrd-progress.is-error {
      border-color: #fecaca;
      background: #fef2f2;
      color: #991b1b;
    }
    .xrd-progress-stage { display: none; }
    .xrd-progress-stage.is-visible { display: block; }
    .xrd-report-progress-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 7px;
      font-weight: 700;
    }
    .xrd-report-progress-row > * {
      margin-bottom: 12px;
      margin-right: 12px;
}
    .xrd-report-progress-track {
      overflow: hidden;
      height: 7px;
      border-radius: 999px;
      background: #dbeafe;
    }
    .xrd-report-progress-bar {
      width: 0%;
      height: 100%;
      border-radius: inherit;
      background: var(--blue);
      transition: width 240ms ease;
    }
    .xrd-upload-progress .xrd-report-progress-bar { background: #16a34a; }
    .xrd-progress.is-error .xrd-report-progress-bar { background: #dc2626; }
    .xrd-preview {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 8px;
      overflow: hidden;
      min-height: 720px;
    }
    .xrd-preview iframe {
      width: 100%;
      height: 920px;
      border: 0;
      display: block;
      background: #fff;
    }
    .xrd-transfer {
      display: block;
      padding: 16px;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: #fff;
    }
    .xrd-transfer > * {
      margin-bottom: 12px;
}
    .xrd-transfer-head,
    .xrd-transfer-actions {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
    }
    .xrd-transfer-head > *,.xrd-transfer-actions > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-transfer-head strong { color: var(--ink); }
    .xrd-request-picker {
      display: flex;
      grid-template-columns: auto minmax(240px, 1fr);
      flex-wrap: wrap;
    }
    .xrd-request-picker > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-request-picker > * {
      flex: 0 1 calc(50% - 10px);
      min-width: 0;
      max-width: calc(50% - 10px);
}
    .xrd-request-picker select,
    .xrd-transfer-grid input {
      width: 100%;
      min-width: 0;
      min-height: 40px;
      border: 1px solid #bfd0e4;
      border-radius: 6px;
      background: #fff;
      color: var(--ink);
      padding: 8px 10px;
      font: inherit;
    }
    .xrd-request-detail {
      display: flex;
      flex-wrap: wrap;
      min-height: 22px;
      color: #475569;
      font-size: 13px;
    }
    .xrd-request-detail > * {
      margin-bottom: 7px;
      margin-right: 14px;
}
    .xrd-request-detail.is-empty { color: var(--muted); }
    .xrd-request-detail b { margin-right: 4px; color: #1e3a5f; }
    .xrd-transfer-grid {
      display: flex;
      grid-template-columns: repeat(4, minmax(150px, 1fr));
      flex-wrap: wrap;
    }
    .xrd-transfer-grid > * {
      margin-bottom: 10px;
      margin-right: 10px;
}
    .xrd-transfer-grid > * {
      flex: 0 1 calc(25% - 10px);
      min-width: 0;
      max-width: calc(25% - 10px);
}
    .xrd-transfer-grid label { min-width: 0; color: #475569; font-size: 13px; }
    .xrd-transfer-grid span { display: block; margin-bottom: 5px; font-weight: 700; }
    .xrd-empty {
      height: 720px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--muted);
      font-weight: 700;
    }
    .xrd-busy {
      position: fixed;
      top: 0;
      right: 0;
      bottom: 0;
      left: 0;
      display: none;
      align-items: center;
      justify-content: center;
      background: rgba(255,255,255,.74);
      z-index: 50;
      color: var(--ink);
      font-weight: 700;
    }
    .xrd-busy.show { display: flex; }
    @media (max-width: 900px) {
      .xrd-topbar { align-items: flex-start; padding: 18px 16px; }
      .xrd-brand { display: block; }
      .xrd-brand h1 { font-size: 25px; }
      .xrd-brand span { display: block; margin-top: 4px; white-space: normal; }
      .xrd-main { padding: 14px 12px 24px; }
      .xrd-topbar { flex-wrap: wrap; }
      .xrd-brand { flex: 1 1 100%; }
      .xrd-actions { width: 100%; justify-content: flex-end; }
      button, .xrd-download { min-height: 40px; padding: 8px 11px; font-size: 14px; }
      .xrd-preview iframe { height: 780px; }
      .xrd-request-picker { grid-template-columns: 1fr; }
      .xrd-request-picker > * {
            flex: 0 1 100%;
            min-width: 0;
            max-width: 100%;
      }
      .xrd-transfer-grid { grid-template-columns: repeat(2, minmax(120px, 1fr)); }
      .xrd-transfer-grid > * {
            flex: 0 1 calc(50% - 12px);
            min-width: 0;
            max-width: calc(50% - 12px);
      }
    }

